shell_commands:
node -e "
import('@re-cinq/eslint-plugin-re-lint').then(m => {
  const plugin = m.default ?? m;
  for (const name of ['no-negative-names', 'no-vague-names', 'no-hybrid-class', 'callee-below-caller', 'max-expects']) {
    console.log('=== ' + name + ' ===');
    console.log(plugin.rules[name]?.meta?.docs?.description);
  }
});
"

node -e "
import('@re-cinq/eslint-plugin-re-lint/spec/spec-link-parser.js').then(m => {
  console.log(Object.keys(m));
  const sample = 'Statement text ([validated by: first test](../../src/a.test.ts#L10), [validated by: second test](../../src/b.test.ts#L20)).';
  console.log('misplaced:', m.findMisplacedCoverageLinks(sample));
  if (m.extractCoverageLinks) console.log('extracted:', m.extractCoverageLinks(sample));
  if (m.parseCoverageLinks) console.log('parsed:', m.parseCoverageLinks(sample));
});
"

